import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Ricerca","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/ricerca.md","filePath":"user-guide/ricerca.md"}'),c={name:"user-guide/ricerca.md"};function r(n,e,d,l,s,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="ricerca" tabindex="-1">Ricerca <a class="header-anchor" href="#ricerca" aria-label="Permalink to &quot;Ricerca&quot;">​</a></h1><p>La ricerca è <strong>locale</strong> e <strong>per vault</strong>: l&#39;indice è sul vostro computer (è ricostruibile da <em>Ricostruisci indice</em> nella palette comandi) e non attraversa i vault. Con i vault del cloud il server non vede mai il contenuto delle note.</p><h2 id="selettore-rapido-mod-o" tabindex="-1">Selettore rapido (<code>Mod+O</code>) <a class="header-anchor" href="#selettore-rapido-mod-o" aria-label="Permalink to &quot;Selettore rapido (`Mod+O`)&quot;">​</a></h2><p>Cerca per <strong>nome</strong> (anche parziale, tollera piccoli salti di lettere): note e presentazioni, e dalla 1.7.1 anche <strong>applicazioni</strong> (file <code>.webapp</code>), <strong>lavagne</strong>, <strong>basi</strong> e <strong>disegni</strong>, per nome senza l&#39;estensione. Ogni voce ha l&#39;icona del suo tipo e i lettori di schermo ne leggono il tipo accanto al nome. <code>Invio</code> apre il file nella sua vista, <code>Mod+Invio</code> in una nuova scheda. Se non c&#39;è una nota con quel nome, in fondo all&#39;elenco compare la voce «Crea …», che la crea; una lavagna, una base, un disegno o un&#39;applicazione con lo stesso nome (la lavagna «Road» e la nota «Road» che ancora non c&#39;è) non la toglie. Le note nel cestino (<code>.trash/</code>) e i file nelle cartelle nascoste (con un nome che inizia per punto) non compaiono, come nell&#39;esploratore dei file: questo vale anche per i suggerimenti dei link <code>[[</code>, che restano di sole note. Una presentazione (<code>.marp</code>) o un alias con lo stesso nome toglie la voce «Crea …» (crearla riassegnerebbe i link esistenti).</p><h2 id="cerca-nel-vault-mod-maiusc-f" tabindex="-1">Cerca nel vault (<code>Mod+Maiusc+F</code>) <a class="header-anchor" href="#cerca-nel-vault-mod-maiusc-f" aria-label="Permalink to &quot;Cerca nel vault (`Mod+Maiusc+F`)&quot;">​</a></h2><p>Scrive in una query libera; il risultato mostra i frammenti trovati, con ordinamento per rilevanza, nome o data di modifica. Si trova per <strong>sottostringa</strong> (almeno 3 caratteri). Operatori:</p><table tabindex="0"><thead><tr><th>Operatore</th><th>Esempio</th><th>Significato</th></tr></thead><tbody><tr><td><code>file:</code> / <code>path:</code></td><td><code>file:budget path:&quot;Progetti/2026&quot;</code></td><td>Nome del file / percorso.</td></tr><tr><td><code>content:</code></td><td><code>content:&quot;verbale&quot;</code></td><td>Solo nel testo (non nel nome).</td></tr><tr><td><code>tag:</code></td><td><code>tag:#cliente/acme</code></td><td>Tag, con gerarchia.</td></tr><tr><td><code>line:()</code> <code>block:()</code> <code>section:()</code></td><td><code>line:(foo bar)</code></td><td>Le parole devono comparire nella stessa riga / blocco / sezione.</td></tr><tr><td><code>task:</code> <code>task-todo:</code> <code>task-done:</code></td><td><code>task-todo:&quot;chiamare&quot;</code></td><td>Solo nelle attività (tutte / da fare / completate).</td></tr><tr><td><code>[proprietà:valore]</code></td><td><code>[stato:attivo]</code>, <code>[scadenza:&lt;2026-12-31]</code></td><td>Filtro sulle proprietà tipizzate.</td></tr><tr><td><code>/regex/</code></td><td><code>/\\d{4}-\\d{2}/</code></td><td>Espressione regolare (RE2).</td></tr><tr><td><code>OR</code>, <code>-</code>, <code>( )</code></td><td><code>(a OR b) -c</code></td><td>Booleani e raggruppamento; più termini = AND implicito; <code>&quot;frase esatta&quot;</code>.</td></tr><tr><td><code>match-case:</code> <code>ignore-case:</code></td><td><code>match-case:Clarae notanda</code></td><td>Forza la sensibilità alle maiuscole.</td></tr></tbody></table><p>Le note nel cestino sono escluse, a meno di attivare <em>Includi le note nel cestino</em>.</p><h2 id="ricerche-incorporate" tabindex="-1">Ricerche incorporate <a class="header-anchor" href="#ricerche-incorporate" aria-label="Permalink to &quot;Ricerche incorporate&quot;">​</a></h2><p>Un blocco di codice con linguaggio <code>query</code> mostra i risultati di una ricerca dentro la nota:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>```query</span></span>\n<span class="line"><span>tag:#progetto -task:fatto</span></span>\n<span class="line"><span>```</span></span></code></pre></div><p>Il blocco si aggiorna quando le note cambiano; il pulsante <em>Apri nella ricerca</em> porta i risultati nel pannello di ricerca. Opzioni e limiti sono nelle impostazioni (<em>Includi la nota ospite</em>).</p><h2 id="ricerca-nei-segnalibri" tabindex="-1">Ricerca nei segnalibri <a class="header-anchor" href="#ricerca-nei-segnalibri" aria-label="Permalink to &quot;Ricerca nei segnalibri&quot;">​</a></h2><p>Una ricerca si può salvare come <strong>segnalibro</strong> (<em>Aggiungi una ricerca ai segnalibri</em>) per riaprirla con un clic.</p>',14)])])}const g=o(c,[["render",r]]);export{m as __pageData,g as default};
